    shop.catalog.handle_add_product({"sku": "OLD", "name": "Old", "unit_price_cents": 1, "on_hand": 0})
    shop.api_inactive = True  # placeholder removed below
    from orders.application.catalog_service import CatalogService  # noqa: F401
    shop.fulfilment  # ensure wired
    assert [p["sku"] for p in shop.fulfilment.handle_low_stock(1).body["products"]] == ["OLD"]


def test_low_stock_rejects_invalid_threshold(shop):
    for bad in (-1, True, False, 1.5, "3", None):
        response = shop.fulfilment.handle_low_stock(bad)
        assert response.status == 400
        assert "threshold" in response.body["error"]

